from __future__ import annotations

import json
import logging
from dataclasses import dataclass
from typing import Any, Iterable, Mapping

from backend.auth.contracts import AuditEvent, AuditSink, MutationCommand, MutationResult, MutationWriter
from backend.shared.authz.logging import extract_request_id, redact_http_headers
from backend.shared.authz.models import (
    ActorContext,
    AuthorizationFailure,
    IdentityProvider,
    PermissionCatalog,
)

LOGGER = logging.getLogger(__name__)

_PROVIDER_HEADER = "x-auth-provider"
_GENERIC_CLAIMS_HEADER = "x-auth-claims"
_OIDC_CLAIMS_HEADER = "x-oidc-claims"
_SAML_CLAIMS_HEADER = "x-saml-claims"

_SUBJECT_KEYS = (
    "actor_id",
    "subject_id",
    "sub",
    "oid",
    "nameid",
    "name_id",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier",
    "http://schemas.microsoft.com/identity/claims/objectidentifier",
    "email",
    "upn",
    "preferred_username",
)

_USERNAME_KEYS = (
    "preferred_username",
    "username",
    "user_name",
    "upn",
    "email",
    "nameid",
    "name_id",
    "sub",
    "oid",
)

_DISPLAY_NAME_KEYS = (
    "display_name",
    "name",
    "full_name",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name",
)

_EMAIL_KEYS = (
    "email",
    "mail",
    "emailaddress",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress",
)

_GROUP_KEYS = (
    "groups",
    "group",
    "group_refs",
    "memberof",
    "memberOf",
    "http://schemas.xmlsoap.org/claims/group",
    "http://schemas.microsoft.com/ws/2008/06/identity/claims/groups",
)

_ROLE_KEYS = (
    "roles",
    "role",
    "http://schemas.microsoft.com/ws/2008/06/identity/claims/role",
)

_PERMISSION_KEYS = (
    "permissions",
    "permission",
    "entitlements",
)

_SCOPE_KEYS = (
    "scope",
    "scp",
)

_ACTIVE_KEYS = (
    "active",
    "is_active",
    "enabled",
    "account_enabled",
    "accountexpired",
)


@dataclass(frozen=True)
class AuthenticatedEnvelope:
    provider: IdentityProvider
    claims: Mapping[str, Any]


def _as_text(value: Any) -> str | None:
    if value is None:
        return None
    if isinstance(value, str):
        stripped = value.strip()
        return stripped or None
    if isinstance(value, (int, float, bool)):
        return str(value)
    return None


def _iter_claim_values(value: Any) -> list[Any]:
    if value is None:
        return []

    if isinstance(value, (list, tuple, set, frozenset)):
        flattened: list[Any] = []
        for item in value:
            flattened.extend(_iter_claim_values(item))
        return flattened

    return [value]


def _flatten_claim_values(value: Any) -> list[str]:
    flattened: list[str] = []
    for candidate in _iter_claim_values(value):
        text = _as_text(candidate)
        if text:
            flattened.append(text)
    return flattened


def _as_bool(value: Any) -> bool | None:
    if isinstance(value, bool):
        return value

    if isinstance(value, int):
        if value == 1:
            return True
        if value == 0:
            return False

    if isinstance(value, str):
        normalized = value.strip().casefold()
        if normalized in {"true", "1", "yes", "y", "active", "enabled"}:
            return True
        if normalized in {"false", "0", "no", "n", "inactive", "disabled"}:
            return False

    return None


def _first_claim_text(claims: Mapping[str, Any], keys: Iterable[str]) -> str | None:
    for key in keys:
        if key not in claims:
            continue
        for candidate in _flatten_claim_values(claims[key]):
            text = _as_text(candidate)
            if text:
                return text
    return None


def _first_claim_bool(claims: Mapping[str, Any], keys: Iterable[str]) -> bool | None:
    for key in keys:
        if key not in claims:
            continue
        for candidate in _iter_claim_values(claims[key]):
            value = _as_bool(candidate)
            if value is not None:
                return value
    return None


def _collect_refs(claims: Mapping[str, Any], keys: Iterable[str]) -> tuple[str, ...]:
    values: set[str] = set()
    for key in keys:
        if key not in claims:
            continue
        for raw in _flatten_claim_values(claims[key]):
            for part in raw.split():
                cleaned = part.strip().casefold()
                if cleaned:
                    values.add(cleaned)
    return tuple(sorted(values))


def _collect_permissions(claims: Mapping[str, Any]) -> frozenset[str]:
    granted: set[str] = set()

    for key in _PERMISSION_KEYS:
        if key not in claims:
            continue
        for raw in _flatten_claim_values(claims[key]):
            cleaned = raw.strip().casefold()
            if cleaned:
                granted.add(cleaned)

    for key in _SCOPE_KEYS:
        if key not in claims:
            continue
        for raw in _flatten_claim_values(claims[key]):
            for scope in raw.split():
                cleaned = scope.strip().casefold()
                if cleaned:
                    granted.add(cleaned)

    return frozenset(sorted(granted))


def _normalize_username(value: str) -> str:
    return value.strip().casefold()


class ClaimNormalizer:
    def __init__(
        self,
        permission_catalog: PermissionCatalog | None = None,
    ) -> None:
        self._permission_catalog = permission_catalog or PermissionCatalog.from_raw()

    def normalize(
        self,
        *,
        provider: IdentityProvider,
        claims: Mapping[str, Any],
    ) -> ActorContext:
        subject = _first_claim_text(claims, _SUBJECT_KEYS)
        if not subject:
            raise AuthorizationFailure(
                status_code=401,
                detail="Authenticated identity missing stable subject claim.",
            )

        username = _first_claim_text(claims, _USERNAME_KEYS) or subject
        display_name = _first_claim_text(claims, _DISPLAY_NAME_KEYS) or username
        email = _first_claim_text(claims, _EMAIL_KEYS)
        groups = _collect_refs(claims, _GROUP_KEYS)
        roles = _collect_refs(claims, _ROLE_KEYS)
        active = _first_claim_bool(claims, _ACTIVE_KEYS)
        direct_permissions = _collect_permissions(claims)
        mapped_permissions = self._permission_catalog.permissions_for(
            groups=groups,
            roles=roles,
        )
        permissions = frozenset(sorted(set(direct_permissions).union(mapped_permissions)))

        return ActorContext(
            actor_id=f"{provider.value}:{subject.strip()}",
            provider=provider,
            subject=subject.strip(),
            username=_normalize_username(username),
            display_name=display_name.strip(),
            active=True if active is None else active,
            email=_normalize_username(email) if email else None,
            groups=groups,
            roles=roles,
            permissions=permissions,
        )


class AuthSessionService:
    def __init__(
        self,
        *,
        permission_catalog: PermissionCatalog | None = None,
        logger: logging.Logger | None = None,
    ) -> None:
        self._normalizer = ClaimNormalizer(permission_catalog=permission_catalog)
        self._logger = logger or LOGGER

    def authenticate_headers(
        self,
        headers: Mapping[str, str],
        *,
        request_id: str | None = None,
    ) -> ActorContext:
        effective_request_id = request_id or extract_request_id(headers)
        envelope = self._extract_envelope(headers, request_id=effective_request_id)
        actor = self._normalizer.normalize(
            provider=envelope.provider,
            claims=envelope.claims,
        )

        if not actor.active:
            self._logger.info(
                "auth_inactive request_id=%s actor_id=%s",
                effective_request_id,
                actor.actor_id,
            )
            raise AuthorizationFailure(
                status_code=403,
                detail="Caller account is inactive.",
            )

        self._logger.debug(
            "auth_authenticated request_id=%s provider=%s actor_id=%s headers=%s",
            effective_request_id,
            actor.provider.value,
            actor.actor_id,
            redact_http_headers(headers),
        )
        return actor

    def require_permissions(
        self,
        actor: ActorContext,
        required_permissions: Iterable[str],
        *,
        request_id: str | None = None,
    ) -> None:
        required = {
            str(permission).strip().casefold()
            for permission in required_permissions
            if str(permission).strip()
        }
        missing = sorted(permission for permission in required if permission not in actor.permissions)

        if missing:
            self._logger.info(
                "auth_forbidden request_id=%s actor_id=%s",
                request_id or "-",
                actor.actor_id,
            )
            raise AuthorizationFailure(
                status_code=403,
                detail="Caller does not have the required permission.",
            )

    def execute_authorized_write(
        self,
        *,
        actor: ActorContext,
        required_permission: str,
        operation: str,
        target_id: str,
        payload: Mapping[str, Any],
        writer: MutationWriter,
        audit_sink: AuditSink,
        request_id: str | None = None,
    ) -> MutationResult:
        self.require_permissions(actor, [required_permission], request_id=request_id)

        command = MutationCommand(
            operation=operation,
            target_id=target_id,
            payload=payload,
            actor_id=actor.actor_id,
            actor_username=actor.username,
            actor_permissions=actor.permissions,
        )
        result = writer.write(command)

        audit_sink.record(
            AuditEvent(
                event_type=operation,
                actor_id=actor.actor_id,
                target_id=target_id,
                details={
                    "mutation_id": result.mutation_id,
                    "payload_keys": sorted(str(key) for key in payload.keys()),
                },
            ),
        )
        return result

    def _extract_envelope(
        self,
        headers: Mapping[str, str],
        *,
        request_id: str,
    ) -> AuthenticatedEnvelope:
        normalized_headers = {str(key).lower(): value for key, value in headers.items()}
        provider = self._resolve_provider(normalized_headers, request_id=request_id)
        claims_payload = self._resolve_claims_payload(normalized_headers, provider)

        if provider is None or claims_payload is None:
            self._logger.warning(
                "auth_rejected request_id=%s reason=%s headers=%s",
                request_id,
                "anonymous_or_missing_verified_claims",
                redact_http_headers(normalized_headers),
            )
            raise AuthorizationFailure(
                status_code=401,
                detail="Authentication required.",
            )

        try:
            parsed_claims = json.loads(claims_payload)
        except json.JSONDecodeError:
            self._logger.warning(
                "auth_rejected request_id=%s reason=%s provider=%s headers=%s",
                request_id,
                "invalid_claims_json",
                provider.value,
                redact_http_headers(normalized_headers),
            )
            raise AuthorizationFailure(
                status_code=401,
                detail="Authentication claims are invalid.",
            ) from None

        if not isinstance(parsed_claims, dict):
            self._logger.warning(
                "auth_rejected request_id=%s reason=%s provider=%s headers=%s",
                request_id,
                "claims_not_object",
                provider.value,
                redact_http_headers(normalized_headers),
            )
            raise AuthorizationFailure(
                status_code=401,
                detail="Authentication claims are invalid.",
            )

        return AuthenticatedEnvelope(
            provider=provider,
            claims=parsed_claims,
        )

    def _resolve_provider(
        self,
        headers: Mapping[str, str],
        *,
        request_id: str,
    ) -> IdentityProvider | None:
        explicit_provider = headers.get(_PROVIDER_HEADER)
        if explicit_provider:
            value = explicit_provider.strip().casefold()
            if value == IdentityProvider.OIDC.value:
                return IdentityProvider.OIDC
            if value == IdentityProvider.SAML.value:
                return IdentityProvider.SAML
            self._logger.warning(
                "auth_rejected request_id=%s reason=%s headers=%s",
                request_id,
                "unsupported_provider",
                redact_http_headers(headers),
            )
            raise AuthorizationFailure(
                status_code=401,
                detail="Unsupported authentication provider.",
            )

        if _OIDC_CLAIMS_HEADER in headers:
            return IdentityProvider.OIDC
        if _SAML_CLAIMS_HEADER in headers:
            return IdentityProvider.SAML
        return None

    def _resolve_claims_payload(
        self,
        headers: Mapping[str, str],
        provider: IdentityProvider | None,
    ) -> str | None:
        if _GENERIC_CLAIMS_HEADER in headers:
            return headers[_GENERIC_CLAIMS_HEADER]

        if provider == IdentityProvider.OIDC:
            return headers.get(_OIDC_CLAIMS_HEADER)

        if provider == IdentityProvider.SAML:
            return headers.get(_SAML_CLAIMS_HEADER)

        return None
