from __future__ import annotations

from fastapi import APIRouter, Depends, Request

from backend.auth.contracts import (
    ActorResponse,
    AuditSink,
    MutationWriter,
    PermissionCatalog,
    ProtectedWriteRequest,
    ProtectedWriteResponse,
)
from backend.auth.implementation import AuthSessionService
from backend.shared.authz.dependencies import build_current_actor_dependency, build_permission_dependency
from backend.shared.authz.logging import extract_request_id
from backend.shared.authz.models import ActorContext


def create_auth_router(
    *,
    mutation_writer: MutationWriter,
    audit_sink: AuditSink,
    permission_catalog: PermissionCatalog | None = None,
    auth_service: AuthSessionService | None = None,
) -> APIRouter:
    service = auth_service or AuthSessionService(permission_catalog=permission_catalog)
    router = APIRouter(tags=["auth"])

    current_actor = build_current_actor_dependency(service)
    require_documents_write = build_permission_dependency(service, "documents.write")

    @router.get("/auth/me", response_model=ActorResponse)
    def get_me(actor: ActorContext = Depends(current_actor)) -> ActorResponse:
        return ActorResponse(
            actor_id=actor.actor_id,
            provider=actor.provider,
            subject=actor.subject,
            username=actor.username,
            display_name=actor.display_name,
            active=actor.active,
            email=actor.email,
            groups=list(actor.groups),
            roles=list(actor.roles),
            permissions=sorted(actor.permissions),
        )

    @router.post("/auth/protected-write", response_model=ProtectedWriteResponse)
    def protected_write(
        request: Request,
        write_request: ProtectedWriteRequest,
        actor: ActorContext = Depends(require_documents_write),
    ) -> ProtectedWriteResponse:
        result = service.execute_authorized_write(
            actor=actor,
            required_permission="documents.write",
            operation="documents.write",
            target_id=write_request.target_id,
            payload=write_request.payload,
            writer=mutation_writer,
            audit_sink=audit_sink,
            request_id=extract_request_id(request.headers),
        )
        return ProtectedWriteResponse(
            mutation_id=result.mutation_id,
            status=result.status,
            target_id=write_request.target_id,
            actor_id=actor.actor_id,
        )

    return router
