from __future__ import annotations

from typing import Any, Mapping

_REQUEST_ID_HEADERS = (
    "x-request-id",
    "x-correlation-id",
)

_SENSITIVE_HEADERS = frozenset(
    {
        "authorization",
        "proxy-authorization",
        "cookie",
        "set-cookie",
        "x-auth-claims",
        "x-oidc-claims",
        "x-saml-claims",
        "x-saml-assertion",
        "x-id-token",
        "x-access-token",
    },
)


def redact_http_headers(headers: Mapping[str, Any]) -> dict[str, str]:
    redacted: dict[str, str] = {}

    for key, value in headers.items():
        lowered = str(key).lower()

        if lowered in _SENSITIVE_HEADERS or any(
            token in lowered for token in ("token", "assertion", "claim", "cookie")
        ):
            redacted[lowered] = "[REDACTED]"
            continue

        redacted[lowered] = str(value)

    return redacted


def extract_request_id(headers: Mapping[str, Any]) -> str:
    normalized_headers = {str(key).lower(): str(value) for key, value in headers.items()}

    for key in _REQUEST_ID_HEADERS:
        candidate = normalized_headers.get(key, "").strip()
        if candidate:
            return candidate

    return "-"
