from __future__ import annotations

from collections.abc import Callable

from fastapi import Depends, HTTPException, Request

from backend.auth.implementation import AuthSessionService
from backend.shared.authz.logging import extract_request_id
from backend.shared.authz.models import ActorContext, AuthorizationFailure


def build_current_actor_dependency(service: AuthSessionService) -> Callable[[Request], ActorContext]:
    def dependency(request: Request) -> ActorContext:
        try:
            return service.authenticate_headers(
                request.headers,
                request_id=extract_request_id(request.headers),
            )
        except AuthorizationFailure as exc:
            raise HTTPException(status_code=exc.status_code, detail=exc.detail) from exc

    return dependency


def build_permission_dependency(
    service: AuthSessionService,
    permission: str,
) -> Callable[..., ActorContext]:
    current_actor = build_current_actor_dependency(service)

    def dependency(
        request: Request,
        actor: ActorContext = Depends(current_actor),
    ) -> ActorContext:
        try:
            service.require_permissions(
                actor,
                [permission],
                request_id=extract_request_id(request.headers),
            )
        except AuthorizationFailure as exc:
            raise HTTPException(status_code=exc.status_code, detail=exc.detail) from exc
        return actor

    return dependency
